import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";
import { Input, type InputProps } from "./input";

export interface InputGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Place the addon after the field. */
  end?: boolean;
}

const styles = stylex.create({
  group: {
    display: "flex",
    alignItems: "stretch",
    boxSizing: "border-box",
    width: "100%",
    height: raster.controlH,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: {
      default: raster.divider,
      ":focus-within": raster.accent,
    },
    borderRadius: {
      default: raster.radiusSm,
      ["@media (max-width: 640px)"]: 0,
    },
    backgroundColor: "var(--bg)",
    overflow: "hidden",
  },
  addon: {
    display: "flex",
    alignItems: "center",
    paddingInline: {
      default: 10,
      ["@media (max-width: 640px)"]: 14,
    },
    paddingBlock: 0,
    fontSize: {
      default: 13,
      ["@media (max-width: 640px)"]: raster.controlFs,
    },
    fontWeight: 500,
    letterSpacing: "-0.01em",
    color: raster.gray,
    backgroundColor: raster.tableAlt,
    whiteSpace: "nowrap",
    minHeight: {
      default: null,
      ["@media (max-width: 640px)"]: raster.hit,
    },
    borderInlineStartWidth: raster.hairline,
    borderInlineStartStyle: "solid",
    borderInlineStartColor: raster.divider,
  },
  firstAddon: {
    borderInlineStartWidth: 0,
  },
});

/** Addon and field share one hairline. */
export function InputGroup({ end, className, style, children, ...props }: InputGroupProps) {
  const sx = rs(["rs-input-group", end && "rs-input-group-end", className], styles.group);
  return (
    <div {...props} className={sx.className} style={{ ...sx.style, ...style }}>
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child) && child.type === Input) {
          const next = child.props as InputProps;
          return React.cloneElement(child as React.ReactElement<InputProps>, {
            plain: next.plain ?? true,
            grouped: next.grouped ?? true,
          });
        }
        return child;
      })}
    </div>
  );
}

export function InputAddon({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-input-addon", className], styles.addon);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Label rendered above the field at 12px. */
  label?: React.ReactNode;
  /** Marks the field as validated: ink border and ink feedback text. */
  ok?: boolean;
  /** Quiet feedback line under the field. */
  feedback?: React.ReactNode;
  /** Control only — no field stack. For Field / InputGroup. */
  plain?: boolean;
  /** Flush into an InputGroup: no own stroke. */
  grouped?: boolean;
}

const styles = stylex.create({
  field: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: 8,
  },
  label: {
    fontSize: {
      default: 12,
      ["@media (max-width: 640px)"]: raster.controlLabel,
    },
    fontWeight: 600,
    color: raster.gray,
    letterSpacing: "-0.01em",
    lineHeight: "16px",
  },
  input: {
    boxSizing: "border-box",
    height: raster.controlH,
    minHeight: {
      default: null,
      ["@media (max-width: 640px)"]: raster.hit,
    },
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: {
      default: raster.divider,
      ":focus": raster.accent,
    },
    borderRadius: {
      default: raster.radiusSm,
      ["@media (max-width: 640px)"]: 0,
    },
    appearance: "none",
    WebkitAppearance: "none",
    backgroundColor: "var(--bg)",
    color: "var(--text)",
    caretColor: "var(--text)",
    fontSize: {
      default: 14,
      ["@media (max-width: 640px)"]: 16,
    },
    lineHeight: `calc(${raster.controlH} - 2px)`,
    paddingInline: {
      default: 12,
      ["@media (max-width: 640px)"]: 14,
    },
    paddingBlock: 0,
    outline: "none",
    fontFamily: "inherit",
    ":-webkit-autofill": {
      WebkitTextFillColor: "var(--text)",
      caretColor: "var(--text)",
      backgroundColor: "var(--bg)",
      boxShadow: "inset 0 0 0 1000px var(--bg)",
    },
  },
  grouped: {
    borderWidth: 0,
    borderRadius: 0,
    height: "100%",
    minHeight: {
      default: null,
      ["@media (max-width: 640px)"]: raster.hit,
    },
    flexGrow: 1,
    minWidth: 0,
    backgroundColor: "var(--bg)",
    color: "var(--text)",
  },
  full: {
    width: "100%",
  },
  ok: {
    borderColor: raster.ink,
  },
  feedback: {
    display: "flex",
    alignItems: "center",
    gap: 8,
    fontSize: {
      default: 12,
      ["@media (max-width: 640px)"]: 14,
    },
    fontWeight: 500,
    color: raster.gray,
    letterSpacing: "-0.01em",
    lineHeight: "16px",
    margin: 0,
    minHeight: 16,
  },
  feedbackOk: {
    color: raster.ink,
  },
});

export const Input = React.forwardRef<HTMLInputElement, InputProps>(function Input(
  { label, ok, feedback, plain, grouped, className, style, id, ...props },
  ref,
) {
  const autoId = React.useId();
  const inputId = id ?? autoId;
  const sx = rs(
    ["rs-input", !grouped && "rs-input-full", ok && "rs-input-ok", className],
    styles.input,
    !grouped && styles.full,
    ok && styles.ok,
    grouped && styles.grouped,
  );
  const control = (
    <input
      ref={ref}
      id={inputId}
      {...props}
      className={sx.className}
      style={{ ...sx.style, ...style }}
    />
  );
  if (plain || grouped) return control;
  const field = rs(["rs-field"], styles.field);
  const lab = rs(["rs-field-label"], styles.label);
  const fb = rs(["rs-feedback", ok && "rs-feedback-ok"], styles.feedback, ok && styles.feedbackOk);
  return (
    <div className={field.className} style={field.style}>
      {label != null && (
        <label className={lab.className} style={lab.style} htmlFor={inputId}>
          {label}
        </label>
      )}
      {control}
      {feedback != null && (
        <span className={fb.className} style={fb.style}>
          {feedback}
        </span>
      )}
    </div>
  );
});

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
